mapper.select:

where del_flag = '0'

    AND task_id = #{taskId}


    AND person_id = #{personId}


    AND period = #{period}


    AND completed = #{completed}

order by deadline asc

mapper.update:
update sys_task_instance
task_name = #{taskName}, person_name = #{personName}, deadline = #{deadline}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where id = #{id}

mapper.select:

where task_id = #{taskId} and person_id = #{personId}
      and period >= #{startDate} and period <= #{endDate} and del_flag = '0'
order by period, deadline asc
